import (
	"context"
	"time"
)

func retry(ctx context.Context, maxAttempts int, delay time.Duration, run func(context.Context) error) error {
	for attempt := 0; attempt < maxAttempts; attempt++ {
		err := run(ctx)
		if err == nil || attempt+1 == maxAttempts {
			return err
		}
		time.Sleep(delay)
	}
	return nil
}

