from collections.abc import Iterable, Mapping

def weekly_summary(readings: Iterable[Mapping[str, object]]) -> dict[str, dict[str, int]]:
    summary: dict[str, dict[str, int]] = {}
    for reading in readings:
        site = str(reading["site"])
        value = float(reading["phosphorus_mg_kg"])
        counts = summary.setdefault(site, {"normal": 0, "out_of_range": 0})
        if 8.0 <= value <= 30.0:
            counts["normal"] += 1
        else:
            counts["out_of_range"] += 1
    return summary

