        .chars()
        .filter(|ch| !ch.is_whitespace())
        .map(|ch| {
            if ch.is_ascii_digit() {
                Token::Number(ch.to_string())
            } else if ch.is_ascii_alphabetic() {
                Token::Identifier(ch.to_string())
            } else {
                Token::Operator(ch)
            }
        })
        .collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Number(String),
    Identifier(String),
    Operator(char),
}

pub fn tokenize(source: &str) -> Vec<Token> {
    source
        .chars()
        .filter(|ch| !ch.is_whitespace())
        .map(|ch| {
            if ch.is_ascii_digit() {
                Token::Number(ch.to_string())
            } else if ch.is_ascii_alphabetic() {
                Token::Identifier(ch.to_string())
            } else {
                Token::Operator(ch)
            }
        })
        .collect()
}

