"""Monthly category budget calculations."""
import os
from datetime import datetime
from zoneinfo import ZoneInfo


def monthly_category_usage(budgets, transactions, year, month, account_timezone=None):
    timezone = account_timezone or os.getenv("FINANCE_ACCOUNT_TIMEZONE", "UTC")
    zone = ZoneInfo(timezone)
    spent = {category: 0.0 for category in budgets}
    for item in transactions:
        stamp = datetime.fromisoformat(item["date"])
        stamp = stamp.replace(tzinfo=zone) if stamp.tzinfo is None else stamp.astimezone(zone)
        if (stamp.year, stamp.month) == (year, month) and item.get("kind", "expense") == "expense":
            category = item["category"]
            spent[category] = spent.get(category, 0.0) + float(item["amount"])
    return {
        category: {
            "budget": float(limit),
            "spent": round(spent[category], 2),
            "remaining": round(float(limit) - spent[category], 2),
            "percent_used": round(spent[category] / float(limit) * 100, 2) if float(limit) else 0.0,
        }
        for category, limit in budgets.items()
    }

