"""Load pressure-drop readings from the partner export."""
import csv
from pathlib import Path

KPA_TO_PSI = 0.1450377377


def load_pressure_drops(csv_path: str | Path) -> dict[str, float]:
    """Return each section's first pressure reading in psi."""
    readings: dict[str, float] = {}
    with Path(csv_path).open("r", newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            section_id = row["section_id"].strip()
            if section_id and section_id not in readings:
                readings[section_id] = float(row["pressure_drop_kpa"]) * KPA_TO_PSI
    return readings

