  site: string;
  acuity: string;
};

export type SiteSummary = {
  site: string;
  normal: number;
  outOfRange: number;
};

export function weeklySummary(readings: Reading[]): SiteSummary[] {
  const bySite = new Map<string, SiteSummary>();
  for (const reading of readings) {
    const row = bySite.get(reading.site) ?? {
      site: reading.site,
      normal: 0,
      outOfRange: 0,
    };
    if (reading.acuity === "20/20") row.normal += 1;
    else row.outOfRange += 1;
    bySite.set(reading.site, row);
  }
  return [...bySite.values()];
}

