import re
from fractions import Fraction

_AMOUNT = re.compile(r"^(?P<quantity>\d+\s+\d+/\d+|\d+/\d+|\d+(?:\.\d+)?)\s+(?P<unit>[A-Za-z]+)\s+(?P<name>.+)$")


def parse_ingredient(line: str) -> dict[str, object]:
    """Return the quantity, source unit spelling, and ingredient name."""
    match = _AMOUNT.fullmatch(line.strip())
    if match is None:
        raise ValueError(f"Invalid ingredient line: {line!r}")
    raw = match.group("quantity")
    if " " in raw:
        whole, fraction = raw.split()
        quantity = Fraction(whole) + Fraction(fraction)
    else:
        quantity = Fraction(raw)
    return {
        "quantity": quantity,
        "unit": match.group("unit"),
        "name": match.group("name").strip(),
    }

