"""Relative-tolerance comparisons for floating-point sensor readings."""


def within_relative_tolerance(left: float, right: float, rel_tol: float = 0.025) -> bool:
    """Return whether readings differ by at most rel_tol times their larger magnitude."""
    if rel_tol < 0:
        raise ValueError("rel_tol must be non-negative")
    return abs(left - right) <= rel_tol * max(abs(left), abs(right))

