package reports;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class Revenue {
    public record Order(LocalDate date, String region, BigDecimal amount) { }

    private Revenue() { }

    public static Map<YearMonth, Map<String, BigDecimal>> monthlyByRegion(List<Order> orders) {
        Map<YearMonth, Map<String, BigDecimal>> totals = new LinkedHashMap<>();
        for (Order order : orders) {
            YearMonth month = YearMonth.from(order.date());
            totals.computeIfAbsent(month, ignored -> new LinkedHashMap<>())
                    .merge(order.region(), order.amount(), BigDecimal::add);
        }
        return totals;
    }
}

