def transpose(rows):
    """Return columns in left-to-right order."""
    if not rows:
        return []
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError("rows must have equal lengths")
    return [list(column) for column in zip(*rows)]

