package jobs

import (
	"fmt"
	"strings"
)

type Job struct {
	Name  string
	State string
}

func FormatJobs(jobs []Job) string {
	if len(jobs) == 0 {
		return ""
	}
	width := len("JOB")
	for _, job := range jobs {
		if len(job.Name) > width {
			width = len(job.Name)
		}
	}
	var out strings.Builder
	fmt.Fprintf(&out, "%-*s  %s\n", width, "JOB", "STATE")
	for _, job := range jobs {
		fmt.Fprintf(&out, "%-*s  %s\n", width, job.Name, job.State)
	}
	return strings.TrimSuffix(out.String(), "\n")
}

