package zones

type Point struct {
	Lon float64
	Lat float64
}

func Contains(point Point, polygon []Point) bool {
	if len(polygon) < 3 {
		return false
	}

	inside := false
	j := len(polygon) - 1
	for i := 0; i < len(polygon); i++ {
		a, b := polygon[i], polygon[j]
		if (a.Lat > point.Lat) != (b.Lat > point.Lat) {
			lonAtLatitude := (b.Lon-a.Lon)*(point.Lat-a.Lat)/(b.Lat-a.Lat) + a.Lon
			if point.Lon < lonAtLatitude {
				inside = !inside
			}
		}
		j = i
	}
	return inside
}

