use crate::ModPowError;

pub fn modpow(base: u64, exponent: u64, modulus: u64) -> Result<u64, ModPowError> {
    {
        if modulus == 0 {
            return Err(ModPowError::ZeroModulus);
        }
        let m = u128::from(modulus);
        let mut factor = u128::from(base) % m;
        let mut accumulator = 1u128 % m;
        let mut power = exponent;
        while power != 0 {
            if power & 1 == 1 {
                accumulator = (accumulator * factor) % m;
            }
            factor = (factor * factor) % m;
            power >>= 1;
        }
        Ok(accumulator as u64)
    }
}

