def order_targets(dependencies):
    targets = list(dependencies)
    remaining = {target: set(dependencies[target]) for target in targets}
    unknown = {dep for required in remaining.values() for dep in required if dep not in remaining}
    if unknown:
        raise ValueError(f"unknown dependencies: {sorted(unknown)}")

    ordered = []
    ready = [target for target in targets if not remaining[target]]
    while ready:
        target = ready.pop(0)
        ordered.append(target)
        for candidate in targets:
            if target in remaining[candidate]:
                remaining[candidate].remove(target)
                if not remaining[candidate]:
                    ready.append(candidate)

    if len(ordered) != len(targets):
        raise ValueError("dependency cycle")
    return ordered

