def diff_dirs(left: str | Path, right: str | Path) -> list[str]:
    """Return relative paths whose files are missing or have different bytes."""
    left_root, right_root = Path(left), Path(right)

    def index(root: Path) -> dict[str, Path]:
        return {
            path.relative_to(root).as_posix(): path
            for path in root.rglob("*")
            if path.is_file()
        }

    left_files, right_files = index(left_root), index(right_root)
    changed = []
    for relative in sorted(left_files.keys() | right_files.keys()):
        left_path, right_path = left_files.get(relative), right_files.get(relative)
        if left_path is None or right_path is None:
            changed.append(relative)
        elif left_path.read_bytes() != right_path.read_bytes():
            changed.append(relative)
    return changed

