import csv
import io


def import_phosphorus(csv_text: str) -> list[dict[str, str | float]]:
    reader = csv.DictReader(io.StringIO(csv_text))
    required = {"field_code", "phosphorus_ppm"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        raise ValueError("CSV must include field_code and phosphorus_ppm")

    records = []
    for line_number, row in enumerate(reader, start=2):
        field_code = (row.get("field_code") or "").strip()
        reading = (row.get("phosphorus_ppm") or "").strip()
        if not field_code:
            raise ValueError(f"missing field_code on row {line_number}")
        if not reading:
            raise ValueError(f"missing phosphorus_ppm on row {line_number}")
        try:
            phosphorus_ppm = float(reading)
        except ValueError as exc:
            raise ValueError(f"invalid phosphorus_ppm on row {line_number}") from exc
        records.append({"field_code": field_code, "phosphorus_ppm": phosphorus_ppm})
    return records

