package server

import (
	"fmt"
	"strconv"
	"strings"
)

func ParsePort(value string) (int, error) {
	if value == "" {
		return 0, fmt.Errorf("port is empty")
	}
	if strings.TrimSpace(value) != value {
		return 0, fmt.Errorf("port %q has surrounding whitespace", value)
	}
	port, err := strconv.Atoi(value)
	if err != nil {
		return 0, fmt.Errorf("invalid port %q: %w", value, err)
	}
	if port < 0 {
		return 0, fmt.Errorf("port must be non-negative: %d", port)
	}
	return port, nil
}

