export interface Order {
  id: string;
  total: number;
}

export function findRecent(
  orders: readonly Order[],
  threshold: number,
): Order | null {
  for (let index = orders.length - 1; index >= 0; index -= 1) {
    const order = orders[index];
    if (order && order.total > threshold) return order;
  }
  return null;
}

